(async () => {
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  function setVal(el, v) {
    const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
    setter.call(el, v);
    el.dispatchEvent(new Event('input', {bubbles:true}));
    el.dispatchEvent(new Event('change', {bubbles:true}));
  }
  const cont = Array.from(document.querySelectorAll('button')).find(b => /^continue/i.test((b.innerText||'').replace(/\s+/g,' ').trim()) && b.offsetParent!==null);
  let clickedContinue = false;
  if (cont) { cont.click(); clickedContinue = true; }
  await sleep(8000);
  const boxes = Array.from(document.querySelectorAll('input[type=number]')).filter(i=>i.offsetParent!==null && /^(first|second|third|fourth|fifth|sixth)$/.test(i.id||''));
  let filled = false;
  if (boxes.length) {
    const digits = '978963';
    for (let i=0;i<boxes.length;i++) setVal(boxes[i], i < digits.length ? digits[i] : '');
    filled = true;
    await sleep(500);
    const cfm = Array.from(document.querySelectorAll('button')).find(b => /confirm\s*otp/i.test((b.innerText||'').replace(/\s+/g,' ')) && b.offsetParent!==null);
    if (cfm) cfm.click();
    await sleep(10000);
  }
  return JSON.stringify({
    clickedContinue, boxesFound: boxes.length, filled,
    url: location.href,
    visBtns: Array.from(document.querySelectorAll('button')).filter(b=>b.offsetParent!==null).map(b=>(b.innerText||'').replace(/\s+/g,' ').trim()).filter(Boolean).filter(t=>/login|confirm|otp|send|web|trader|try/i.test(t)).slice(0,8),
    errs: (Array.from(document.querySelectorAll('div,span,p,label')).map(e=>(e.innerText||'').replace(/\s+/g,' ').trim()).filter(t=>/wrong|invalid|incorrect|expired|failed|mismatch|not found/i.test(t) && t.length<100).slice(0,4)),
    txt: (document.body.innerText||'').replace(/\s+/g,' ').slice(0,260)
  });
})()
